# Example code snippet to test regex patterns and their potential performance issues
import re

def test_regex_performance(pattern: str, content: str):
    try:
        match = re.search(pattern, content)
        print(f"Pattern found: {match is not None}")
    except re.error as e:
        print(f"Regex error: {e}")

# Test with a potentially problematic pattern
test_regex_performance(r'(a+)+$', 'a' * 10000)
